    s = str(value).strip()
    if _unreplaced(s):
        return int(default)
    try:
        return int(float(s))
    except Exception:
        return int(default)


def run(protocol: protocol_api.ProtocolContext):
    # Module and Labware
    hs_mod = protocol.load_module(module_name="heaterShakerModuleV1", location=1)
    try:
        cytiva_labware = hs_mod.load_labware('cytiva_96_filterwellplate_1ml')
        protocol.comment('Loaded custom labware cytiva_96_filterwellplate_1ml on Heater-Shaker.')
    except Exception:
        cytiva_labware = hs_mod.load_labware('nest_96_wellplate_200ul_flat')
        protocol.comment('WARNING: custom labware not found; using nest_96_wellplate_200ul_flat as SIM fallback only.')

